package com.muxigame.city;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.*;
import net.minecraft.world.level.block.Blocks;

/** Vacancy succession and hunger demotion, with separate imported-person wealth accounting. */
public final class RuralSuccession {
 static void employ(MinecraftServer s,CityData.City c,UUID id,UUID building){var d=RuralSettlement.get(s);var b=c.buildings.get(building);CityEconomy.require(b!=null&&b.type().equals("工坊")&&c.residents.contains(id),"选择本城工坊与居民");var h=CityHousing.house(c,building);h.workers.removeIf(npc->!CityWorks.living(s,c,npc));CityEconomy.require(h.stage.equals("BUILT"),"工坊尚未竣工");CityEconomy.require(h.workers.contains(id)||h.workers.size()<h.workerLimit,"工坊工人容量不足");CityEconomy.require(CityEconomy.get(s).state.production.stream().noneMatch(j->j.enabled&&j.worker.equals(id)),"先解除原生产岗位");long position=h.baseline.entrySet().stream().filter(e->CityBlockRules.workstation(CityMaintenance.decode(e.getValue()))).map(Map.Entry::getKey).filter(pos->{var site=d.state.sites.get(RuralSettlement.key(c.id,pos));return site==null||site.worker==null||site.worker.equals(id)||!CityWorks.living(s,c,site.worker);}).findFirst().orElseThrow(()->new IllegalArgumentException("工坊需要一个空闲工作方块，请记录含工作台/铁砧的房屋基准"));var p=d.enroll(s,c,id,"工匠 "+id.toString().substring(0,6));CityEconomy.require(!p.dead&&p.age.ordinal()>=2&&p.hunger()<2,"需要健康在世成人");for(var city:CityData.get(s).cities.values())for(var prior:city.housing.houses.values())if(prior!=h)prior.workers.remove(id);for(var site:d.state.sites.values())if(id.equals(site.worker)){site.worker=null;site.vacantSince=0;}var site=d.state.sites.computeIfAbsent(RuralSettlement.key(c.id,position),k->new RuralSettlement.Site());site.city=c.id;site.pos=position;site.kind="artisan";site.worker=id;site.present=true;site.vacantSince=0;h.workers.add(id);h.artisanWorkshop=true;h.production=false;setRole(p,RuralRules.Role.ARTISAN);var w=CityMaintenance.get(s).state.workers.computeIfAbsent(id,k->new CityMaintenance.Worker());w.city=c.id;w.enabled=true;w.artisan=true;w.role="工匠";CityMaintenance.get(s).setDirty();CityMaintenance.enableDataCity(s,c);var economy=CityEconomy.get(s);var life=economy.state.living.get(id);if(life!=null)life.enabled=false;for(var order:economy.state.consumption)if(order.npc.equals(id))order.enabled=false;economy.invalidateIndexes();economy.setDirty();d.setDirty();CityData.get(s).setDirty();}
 static void setRole(RuralRules.Person p,RuralRules.Role role){if(p.role!=role){p.role=role;p.trainedHours=0;p.trainingTicks=0;p.workingTicks=0;p.productionCredit=0;p.cookingCredit=0;p.huntingTicks=0;}}
 static boolean capable(RuralRules.Person p){return p!=null&&!p.dead&&p.age.ordinal()>=2&&p.hunger()<2;}
 static void demote(MinecraftServer s,CityData.City c,RuralRules.Person p){setRole(p,RuralRules.Role.NONE);var d=RuralSettlement.get(s);for(var site:d.state.sites.values())if(p.id.equals(site.worker)){site.worker=null;site.vacantSince=0;}var w=CityMaintenance.get(s).state.workers.get(p.id);if(w!=null){w.enabled=false;CityMaintenance.get(s).setDirty();}for(var h:c.housing.houses.values())h.workers.remove(p.id);p.workStatus="进入最后饥饿阶段，暂离工匠岗位成为居民";d.log(p.name+"濒饿离职转为居民");d.setDirty();}
 static void tick(MinecraftServer s,CityData.City c){var d=RuralSettlement.get(s);long now=Math.max(d.state.simulationTicks,c.works.clock);RuralTools.resignBlocked(s,c,now);for(var p:new ArrayList<>(d.state.people.values()))if(p.role==RuralRules.Role.ARTISAN&&!p.dead&&d.state.families.get(p.family).city.equals(c.id)&&p.hunger()>=2)demote(s,c,p);
  for(var site:new ArrayList<>(d.state.sites.values())){if(!site.city.equals(c.id)||!RuralTools.available(s,site)||!Set.of("farmer","artisan").contains(site.kind))continue;var old=d.state.people.get(site.worker);if(old!=null&&!old.dead){site.vacantSince=0;continue;}if(site.vacantSince==0)site.vacantSince=now+1;
   if(old!=null&&old.spouse!=null){var spouse=d.state.people.get(old.spouse);if(capable(spouse)&&spouse.role==RuralRules.Role.COOK){for(var previous:d.state.sites.values())if(spouse.id.equals(previous.worker)){previous.worker=null;previous.vacantSince=0;}site.worker=spouse.id;site.vacantSince=0;if(site.kind.equals("artisan")){var house=c.buildings.values().stream().filter(b->b.bounds().contains(BlockPos.of(site.pos))).findFirst();if(house.isPresent())employ(s,c,spouse.id,house.get().id());}d.log("配偶接替"+site.kind+"工作点");continue;}}
   if(now+1-site.vacantSince<72000)continue;var candidate=d.state.people.values().stream().filter(RuralSuccession::capable).filter(p->c.residents.contains(p.id)&&d.state.families.get(p.family).city.equals(c.id)&&(p.role==RuralRules.Role.NONE||p.role==RuralRules.Role.VAGRANT)).filter(p->d.state.sites.values().stream().noneMatch(v->p.id.equals(v.worker))).findFirst().orElse(null);
   if(candidate==null){var town=CityTrade.get(s).state.towns.get(c.id);if(town!=null&&town.localOnly)continue;if(d.state.people.size()>=512||c.residents.size()>=4096)continue;candidate=immigrant(s,c,site,old);}if(candidate==null)continue;
   if(site.kind.equals("artisan")){var house=c.buildings.values().stream().filter(b->b.bounds().contains(BlockPos.of(site.pos))).findFirst();if(house.isEmpty())continue;try{employ(s,c,candidate.id,house.get().id());}catch(IllegalArgumentException ex){continue;}}else{site.worker=candidate.id;setRole(candidate,candidate.female?RuralRules.Role.COOK:RuralRules.Role.FARMER);}site.vacantSince=0;c.works.successions++;d.log(candidate.name+"接任"+site.kind+"，未复活死者");d.setDirty();CityData.get(s).setDirty();
  }
  spawn(s,c);
 }
 static RuralRules.Person immigrant(MinecraftServer s,CityData.City c,RuralSettlement.Site site,RuralRules.Person old){var d=RuralSettlement.get(s);var f=old==null?null:d.state.families.get(old.family);if(f==null||RuralRules.reserved(f,d.state.people)>=10){f=new RuralRules.Family();f.id=UUID.randomUUID();f.city=c.id;d.state.families.put(f.id,f);}var p=new RuralRules.Person();p.id=UUID.randomUUID();p.name="流亡者 "+p.id.toString().substring(0,6);p.female=s.overworld().random.nextBoolean();p.role=RuralRules.Role.NONE;d.state.people.put(p.id,p);RuralRules.admit(f,p,d.state.people);c.residents.add(p.id);var e=CityEconomy.get(s);e.state.accounts.put(CityEconomy.person(p.id),50L);e.log(c.works.clock,"MIGRANT_WEALTH","outside_migrant",CityEconomy.person(p.id),50,"新迁入者携带储蓄，不是本地交易收入");c.works.migrantSilver+=50;d.audit(c.id).migrationSilver+=50;c.works.arrivals.put(p.id,site.pos);/* Private boxes retain their family owner when workers change. */return p;}
 static void spawn(MinecraftServer s,CityData.City c){if(c.works.virtual)return;if(c.works.arrivals.isEmpty())return;var l=CityEconomy.level(s,c);for(var entry:new ArrayList<>(c.works.arrivals.entrySet())){var pos=BlockPos.of(entry.getValue());if(!l.hasChunkAt(pos))continue;if(l.getEntity(entry.getKey())!=null){c.works.arrivals.remove(entry.getKey());continue;}var type=BuiltInRegistries.ENTITY_TYPE.getOptional(ResourceLocation.parse("customnpcs:customnpc")).orElse(null);if(type==null)return;BlockPos safe=null;for(var candidate:BlockPos.betweenClosed(pos.offset(-4,-1,-4),pos.offset(4,2,4)))if(l.hasChunkAt(candidate)&&l.getBlockState(candidate).getCollisionShape(l,candidate).isEmpty()&&l.getBlockState(candidate.above()).getCollisionShape(l,candidate.above()).isEmpty()&&!l.getBlockState(candidate.below()).getCollisionShape(l,candidate.below()).isEmpty()){safe=candidate.immutable();break;}if(safe==null)continue;var entity=type.create(l);if(entity==null)return;entity.setUUID(entry.getKey());entity.moveTo(safe.getX()+.5,safe.getY(),safe.getZ()+.5,0,0);entity.setCustomName(Component.literal(RuralSettlement.get(s).state.people.get(entry.getKey()).name));if(entity instanceof Mob mob)mob.setPersistenceRequired();l.addFreshEntity(entity);c.works.arrivals.remove(entry.getKey());break;}}
 static void emergencyNow(MinecraftServer s,CityData.City c){var d=RuralSettlement.get(s);var remaining=new HashMap<UUID,Integer>();for(var p:d.state.people.values())if(!p.dead&&p.role==RuralRules.Role.ARTISAN&&d.state.families.get(p.family).city.equals(c.id)){var f=d.state.families.get(p.family);int shortage=remaining.computeIfAbsent(f.id,k->Math.max(0,RuralRules.demand(f,d.state.people)-RuralCooking.ready(d.stocks(f.id))));int need=Math.max(0,Math.min(shortage,Math.min(p.meal(),(int)Math.ceil(p.maximum()-p.nourishment))));if(need>0){int got=CityWorksFinance.publicMeals(s,c,need);p.nourishment+=got;remaining.put(f.id,shortage-got);}}NpcStorage.refresh(s);d.setDirty();}
 static void aid(MinecraftServer s,CityData.City c,RuralRules.Family f){if(!c.works.emergency)return;var d=RuralSettlement.get(s);int missing=Math.max(0,RuralRules.demand(f,d.state.people)-RuralCooking.ready(d.stocks(f.id)));for(var p:RuralRules.members(f,d.state.people))if(p.role==RuralRules.Role.ARTISAN&&missing>0){int need=Math.min(p.meal(),missing),n=CityWorksFinance.publicMeals(s,c,need);p.nourishment=Math.min(p.maximum()+p.meal(),p.nourishment+n);missing-=n;}}
 static void artisanMeals(MinecraftServer s,CityData.City c){if(RuralSettlement.active(s,c.id))return;var d=RuralSettlement.get(s);for(var f:d.state.families.values())if(f.city.equals(c.id)){var people=RuralRules.members(f,d.state.people).stream().filter(p->p.role==RuralRules.Role.ARTISAN||p.role==RuralRules.Role.VAGRANT).toList();if(people.isEmpty())continue;aid(s,c,f);var stock=d.stocks(f.id);int ready=RuralRules.count(stock,true)+stock.stream().mapToInt(v->Arrays.stream(v.cooked).sum()).sum(),demand=people.stream().mapToInt(RuralRules.Person::meal).sum();int bought=CityWorksFinance.buyMeals(s,c,f,Math.max(0,demand-ready));for(int i=0;i<bought;i++){var next=people.stream().min(Comparator.comparingDouble(p->p.nourishment/p.maximum())).orElseThrow();next.nourishment++;}int beforeBread=RuralRules.count(stock,true),beforeMeat=RuralMeat.total(stock);RuralRules.meal(people,stock);int usedBread=beforeBread-RuralRules.count(stock,true),usedMeat=beforeMeat-RuralMeat.total(stock);d.audit(c.id).breadEaten+=usedBread;d.audit(c.id).meatEaten+=usedMeat;d.state.foodEaten+=usedBread;}NpcStorage.refresh(s);d.setDirty();}
}
